@page "/notifications"
@rendermode InteractiveServer
@using BlazorApp.Services
@inject NotificationService NotificationSvc
@implements IDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (Notifications is not null)
    {
        <span class="badge bg-primary ms-2">@Notifications.Count</span>
    }
</h1>

@if (Notifications is null)
{
    <p><em>Loading...</em></p>
}
else if (Notifications.Count == 0)
{
    <p>No notifications.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in Notifications.OrderByDescending(x => x.Timestamp))
        {
            <li class="list-group-item">
                <strong>@n.Message</strong>
                <small class="text-muted ms-2">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    private CancellationTokenSource? _cts;

    [PersistentState]
    public List<Notification>? Notifications { get; set; }

    protected override async Task OnInitializedAsync()
    {
        // Only fetch if not already restored from prerender state
        Notifications ??= await NotificationSvc.GetNotificationsAsync();
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // Start polling only after the component is interactive in the browser
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        var lastId = Notifications?.MaxBy(n => n.Id)?.Id ?? 0;

        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct);

            // Simulate new notifications arriving on the server
            NotificationSvc.SimulateIncoming();

            var newer = await NotificationSvc.GetNotificationsSinceAsync(lastId);
            if (newer.Count > 0)
            {
                Notifications ??= [];
                Notifications.AddRange(newer);
                lastId = newer.Max(n => n.Id);
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

